import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written in-process double of the pricing downstream (unit price in euros).
const prices = { A: 10, B: 33.5, BIG: 100, CENT: 100.5 }
const pricing = { priceOf: async (sku) => prices[sku] }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' }, body: raw ?? JSON.stringify(body),
})

test('POST /orders creates an order: 201, json, string id, items echoed, total', async () => {
  const res = await post({ items: [{ sku: 'A', qty: 2 }] })
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  const body = await res.json()
  assert.match(body.id, /^\d+$/)
  assert.deepEqual(Object.keys(body).sort(), ['id', 'items', 'total'])
  assert.deepEqual(body.items, [{ sku: 'A', qty: 2 }])
  assert.equal(body.total, 20)
})

test('POST /orders ids are sequential strings', async () => {
  const a = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('POST /orders sums several items', async () => {
  const body = await (await post({ items: [{ sku: 'A', qty: 1 }, { sku: 'B', qty: 2 }] })).json()
  assert.equal(body.total, 77)
})

test('POST /orders total is floored', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — 33.5 floors to 33 (cents are dropped, not rounded)
  const body = await (await post({ items: [{ sku: 'B', qty: 1 }] })).json()
  assert.equal(body.total, 33)
})

test('POST /orders no discount when total is exactly 100', async () => {
  const body = await (await post({ items: [{ sku: 'BIG', qty: 1 }] })).json()
  assert.equal(body.total, 100)
})

test('POST /orders 10% discount when total is above 100', async () => {
  const body = await (await post({ items: [{ sku: 'CENT', qty: 1 }] })).json()
  assert.equal(body.total, 90) // 100.5 - 10.05 = 90.45 -> floor
  const big = await (await post({ items: [{ sku: 'A', qty: 20 }] })).json()
  assert.equal(big.total, 180)
})

test('POST /orders non-numeric qty gives a null total but still 201', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — qty is not validated; NaN serialises as null
  const res = await post({ items: [{ sku: 'A', qty: 'lots' }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

test('POST /orders numeric string qty is coerced', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — "3" is multiplied as a number
  const res = await post({ items: [{ sku: 'A', qty: '3' }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, 30)
})

for (const [name, body, raw] of [
  ['empty items', { items: [] }],
  ['missing items', {}],
  ['items not an array', { items: 'x' }],
  ['invalid JSON', undefined, '{nope'],
  ['empty body', undefined, ''],
]) {
  test(`POST /orders 400 for ${name}`, async () => {
    const res = await post(body, raw)
    assert.equal(res.status, 400)
    assert.equal(res.headers.get('content-type'), 'application/json')
    assert.deepEqual(await res.json(), { error: 'items required' })
  })
}

test('GET /orders/:id returns a created order', async () => {
  const created = await (await post({ items: [{ sku: 'A', qty: 3 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(await res.json(), created)
})

test('GET /orders/:id for an unknown id is 200 with an error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — a missing order answers 200, not 404
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

for (const [method, path] of [
  ['GET', '/orders'], ['DELETE', '/orders/1'], ['PUT', '/orders/1'], ['POST', '/orders/1'],
  ['GET', '/'], ['GET', '/orders/1/items'], ['GET', '/orders/'],
]) {
  test(`${method} ${path} is 404 no route`, async () => {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404)
    assert.equal(res.headers.get('content-type'), 'application/json')
    assert.deepEqual(await res.json(), { error: 'no route' })
  })
}
